"""Finding-bound cycle-05 repairs for bounded/circular storage."""
from __future__ import annotations

from dataclasses import replace


def apply_cycle05(cases):
    by = {case.task_id: case for case in cases}

    def revise(task_id, **changes):
        by[task_id] = replace(by[task_id], **changes)

    revise(
        "segmented-delta-samples",
        header=r'''class SegmentedDeltaSamples{public:explicit SegmentedDeltaSamples(std::size_t);bool append(std::int64_t);std::optional<std::int64_t> at(std::size_t)const;std::vector<std::int64_t> decode()const;std::size_t base_segments()const;private:struct Cell{bool base;std::int64_t value;};std::size_t cap_;std::deque<Cell> cells_;static std::optional<std::int64_t> checked_delta(std::int64_t,std::int64_t);void rebuild(const std::vector<std::int64_t>&);};''',
        reference=r'''SegmentedDeltaSamples::SegmentedDeltaSamples(std::size_t n):cap_(n){if(!n)throw std::invalid_argument("capacity");}std::optional<std::int64_t> SegmentedDeltaSamples::checked_delta(std::int64_t current,std::int64_t previous){if((previous>0&&current<std::numeric_limits<std::int64_t>::min()+previous)||(previous<0&&current>std::numeric_limits<std::int64_t>::max()+previous))throw std::overflow_error("delta");auto value=current-previous;return value>=-32768&&value<=32767?std::optional<std::int64_t>(value):std::nullopt;}void SegmentedDeltaSamples::rebuild(const std::vector<std::int64_t>&values){cells_.clear();for(std::size_t i=0;i<values.size();++i){bool base=true;std::int64_t encoded=values[i];if(i)if(auto delta=checked_delta(values[i],values[i-1])){base=false;encoded=*delta;}cells_.push_back({base,encoded});}}bool SegmentedDeltaSamples::append(std::int64_t v){auto values=decode();if(!values.empty())checked_delta(v,values.back());values.push_back(v);if(values.size()>cap_)values.erase(values.begin());rebuild(values);return true;}std::vector<std::int64_t> SegmentedDeltaSamples::decode()const{std::vector<std::int64_t> out;for(const auto&c:cells_){if(c.base||out.empty())out.push_back(c.value);else out.push_back(out.back()+c.value);}return out;}std::optional<std::int64_t> SegmentedDeltaSamples::at(std::size_t age)const{auto v=decode();return age<v.size()?std::optional<std::int64_t>(v[v.size()-1-age]):std::nullopt;}std::size_t SegmentedDeltaSamples::base_segments()const{return static_cast<std::size_t>(std::count_if(cells_.begin(),cells_.end(),[](auto&c){return c.base;}));}''',
        hidden=r'''int main(){SegmentedDeltaSamples s(3);s.append(-40000);s.append(40000);s.append(40001);CHECK(s.decode()==std::vector<std::int64_t>({-40000,40000,40001}));CHECK(s.base_segments()==2);CHECK(!s.at(3));SegmentedDeltaSamples edge(2);edge.append(std::numeric_limits<std::int64_t>::min());auto before=edge.decode();try{edge.append(0);CHECK(false);}catch(const std::overflow_error&){}CHECK(edge.decode()==before);return failures;}''',
        negative_old='if((previous>0&&current<std::numeric_limits<std::int64_t>::min()+previous)||(previous<0&&current>std::numeric_limits<std::int64_t>::max()+previous))throw std::overflow_error("delta");',
        negative_new='if(previous==current&&false)throw std::overflow_error("delta");',
        negative_reason="zero minus INT64_MIN must be rejected before signed subtraction and without changing retained samples",
    )

    revise(
        "first-write-rollback-stack",
        reference=r'''FirstWriteRollbackStack::FirstWriteRollbackStack(std::size_t n):values_(n),undo_cap_(n){if(!n)throw std::invalid_argument("capacity");}std::optional<std::uint64_t> FirstWriteRollbackStack::checkpoint(){if(next_==std::numeric_limits<std::uint64_t>::max())return std::nullopt;frames_.push_back({next_,{}});return next_++;}bool FirstWriteRollbackStack::assign(std::size_t i,int v){if(i>=values_.size())throw std::invalid_argument("cell");if(!frames_.empty()&&!frames_.back().old.count(i)){if(undo_used_==undo_cap_)return false;frames_.back().old.emplace(i,values_[i]);++undo_used_;}values_[i]=v;return true;}bool FirstWriteRollbackStack::restore(std::uint64_t id){if(frames_.empty()||frames_.back().id!=id)return false;for(auto&x:frames_.back().old)values_[x.first]=x.second;undo_used_-=frames_.back().old.size();frames_.pop_back();return true;}bool FirstWriteRollbackStack::release(std::uint64_t id){if(frames_.empty()||frames_.back().id!=id)return false;auto child=std::move(frames_.back());frames_.pop_back();if(frames_.empty())undo_used_-=child.old.size();else for(auto&x:child.old)if(!frames_.back().old.emplace(x.first,x.second).second)--undo_used_;return true;}std::vector<int> FirstWriteRollbackStack::values()const{return values_;}''',
        hidden=r'''int main(){FirstWriteRollbackStack bounded(1);auto a=bounded.checkpoint();CHECK(a&&bounded.assign(0,1)&&bounded.assign(0,2));auto b=bounded.checkpoint();CHECK(b);CHECK(!bounded.assign(0,3));CHECK(bounded.release(*b));CHECK(bounded.restore(*a));CHECK(bounded.values()==std::vector<int>({0}));FirstWriteRollbackStack nested(2);auto outer=nested.checkpoint();auto inner=nested.checkpoint();CHECK(outer&&inner&&nested.assign(0,7));CHECK(nested.release(*inner));CHECK(nested.restore(*outer));CHECK(nested.values()==std::vector<int>({0,0}));return failures;}''',
        negative_old='auto child=std::move(frames_.back());frames_.pop_back();if(frames_.empty())undo_used_-=child.old.size();else for(auto&x:child.old)if(!frames_.back().old.emplace(x.first,x.second).second)--undo_used_;',
        negative_new='undo_used_-=frames_.back().old.size();frames_.pop_back();',
        negative_reason="discarding a released child frame instead of merging its first writes prevents the parent checkpoint from restoring them",
    )

    revise(
        "neighborhood-hop-bitmap",
        reference=r'''NeighborhoodHopBitmap::NeighborhoodHopBitmap(std::size_t n,std::size_t h):cells_(n),bits_(n),hood_(h){if(!n||h<2||h>64||h>n)throw std::invalid_argument("neighborhood");}std::size_t NeighborhoodHopBitmap::home(int k)const{auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%cells_.size());}std::size_t NeighborhoodHopBitmap::distance(std::size_t a,std::size_t b)const{return (b+cells_.size()-a)%cells_.size();}std::optional<int> NeighborhoodHopBitmap::find(int k)const{auto h=home(k),mask=bits_[h];for(std::size_t d=0;d<hood_;++d)if(mask&(std::uint64_t{1}<<d)){auto i=(h+d)%cells_.size();if(cells_[i]&&cells_[i]->key==k)return cells_[i]->value;}return std::nullopt;}bool NeighborhoodHopBitmap::insert(int k,int v){if(find(k)){auto h=home(k);for(std::size_t d=0;d<hood_;++d){auto i=(h+d)%cells_.size();if(cells_[i]&&cells_[i]->key==k){cells_[i]->value=v;return true;}}}auto old_cells=cells_;auto old_bits=bits_;auto h=home(k);std::size_t free=cells_.size();for(std::size_t scan=0;scan<cells_.size();++scan){auto i=(h+scan)%cells_.size();if(!cells_[i]){free=i;break;}}if(free==cells_.size())return false;while(distance(h,free)>=hood_){bool moved=false;for(std::size_t back=hood_-1;back>0;--back){auto from=(free+cells_.size()-back)%cells_.size();if(!cells_[from])continue;auto source_home=home(cells_[from]->key);auto old_distance=distance(source_home,from),new_distance=distance(source_home,free);if(new_distance<hood_){cells_[free]=cells_[from];cells_[from].reset();bits_[source_home]&=~(std::uint64_t{1}<<old_distance);bits_[source_home]|=std::uint64_t{1}<<new_distance;free=from;moved=true;break;}}if(!moved){cells_=std::move(old_cells);bits_=std::move(old_bits);return false;}}auto d=distance(h,free);cells_[free]=Cell{k,v};bits_[h]|=std::uint64_t{1}<<d;return true;}bool NeighborhoodHopBitmap::erase(int k){auto h=home(k);for(std::size_t d=0;d<hood_;++d){auto i=(h+d)%cells_.size();if(cells_[i]&&cells_[i]->key==k){cells_[i].reset();bits_[h]&=~(std::uint64_t{1}<<d);return true;}}return false;}std::vector<std::uint64_t> NeighborhoodHopBitmap::hop_bits()const{return bits_;}''',
        hidden=r'''int main(){NeighborhoodHopBitmap m(5,3);auto key=std::numeric_limits<int>::min();CHECK(m.insert(key,7));CHECK(m.find(key)==7);CHECK((m.hop_bits()[3]&1)!=0);CHECK(m.erase(key));CHECK(!m.find(key));NeighborhoodHopBitmap full(4,2);CHECK(full.insert(0,1));CHECK(full.insert(4,2));auto before=full.hop_bits();CHECK(!full.insert(8,3));CHECK(full.hop_bits()==before);return failures;}''',
        negative_old='std::size_t NeighborhoodHopBitmap::home(int k)const{auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%cells_.size());}',
        negative_new='std::size_t NeighborhoodHopBitmap::home(int k)const{if(k==std::numeric_limits<int>::min())throw std::invalid_argument("key");auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%cells_.size());}',
        negative_reason="rejecting INT_MIN avoids one undefined negation only by violating the all-int public key domain",
    )

    revise(
        "atomic-dual-key-index",
        reference=r'''AtomicDualKeyIndex::AtomicDualKeyIndex(std::size_t n):pairs_(n),left_(n,-1),right_(n,-1){if(!n)throw std::invalid_argument("capacity");}std::size_t AtomicDualKeyIndex::hash(int k)const{auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%pairs_.size());}std::optional<std::size_t> AtomicDualKeyIndex::find_left(int k)const{auto h=hash(k);for(std::size_t p=0;p<left_.size();++p){int slot=left_[(h+p)%left_.size()];if(slot==-1)return std::nullopt;if(slot>=0&&pairs_[static_cast<std::size_t>(slot)].live&&pairs_[static_cast<std::size_t>(slot)].left==k)return static_cast<std::size_t>(slot);}return std::nullopt;}std::optional<std::size_t> AtomicDualKeyIndex::find_right(int k)const{auto h=hash(k);for(std::size_t p=0;p<right_.size();++p){int slot=right_[(h+p)%right_.size()];if(slot==-1)return std::nullopt;if(slot>=0&&pairs_[static_cast<std::size_t>(slot)].live&&pairs_[static_cast<std::size_t>(slot)].right==k)return static_cast<std::size_t>(slot);}return std::nullopt;}std::size_t AtomicDualKeyIndex::insertion_slot(const std::vector<int>&table,int k)const{auto h=hash(k),first=table.size();for(std::size_t p=0;p<table.size();++p){auto i=(h+p)%table.size();if(table[i]==-2&&first==table.size())first=i;if(table[i]==-1)return first==table.size()?i:first;}return first;}bool AtomicDualKeyIndex::link(int l,int r){auto lp=find_left(l),rp=find_right(r);if(lp||rp)return lp&&rp&&*lp==*rp;if(live_==pairs_.size())return false;auto li=insertion_slot(left_,l),ri=insertion_slot(right_,r);if(li==left_.size()||ri==right_.size())return false;auto slot=static_cast<std::size_t>(std::find_if(pairs_.begin(),pairs_.end(),[](const auto&p){return !p.live;})-pairs_.begin());pairs_[slot]={l,r,true};left_[li]=static_cast<int>(slot);right_[ri]=static_cast<int>(slot);++live_;return true;}std::optional<int> AtomicDualKeyIndex::right_of(int l)const{auto i=find_left(l);return i?std::optional<int>(pairs_[*i].right):std::nullopt;}std::optional<int> AtomicDualKeyIndex::left_of(int r)const{auto i=find_right(r);return i?std::optional<int>(pairs_[*i].left):std::nullopt;}void AtomicDualKeyIndex::unlink_slot(std::size_t slot){for(auto&x:left_)if(x==static_cast<int>(slot))x=-2;for(auto&x:right_)if(x==static_cast<int>(slot))x=-2;pairs_[slot].live=false;--live_;}bool AtomicDualKeyIndex::unlink_left(int l){auto i=find_left(l);if(!i)return false;unlink_slot(*i);return true;}bool AtomicDualKeyIndex::unlink_right(int r){auto i=find_right(r);if(!i)return false;unlink_slot(*i);return true;}''',
        hidden=r'''int main(){AtomicDualKeyIndex b(2);auto lo=std::numeric_limits<int>::min();CHECK(b.link(lo,-2));CHECK(b.right_of(lo)==-2&&b.left_of(-2)==lo);CHECK(b.link(-1,lo));CHECK(b.right_of(-1)==lo&&b.left_of(lo)==-1);CHECK(!b.link(2,3));CHECK(b.unlink_right(-2));CHECK(!b.right_of(lo));return failures;}''',
        negative_old='std::size_t AtomicDualKeyIndex::hash(int k)const{auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%pairs_.size());}',
        negative_new='std::size_t AtomicDualKeyIndex::hash(int k)const{if(k==std::numeric_limits<int>::min())throw std::invalid_argument("key");auto magnitude=k<0?static_cast<std::uint64_t>(-static_cast<std::int64_t>(k)):static_cast<std::uint64_t>(k);return static_cast<std::size_t>(magnitude%pairs_.size());}',
        negative_reason="rejecting INT_MIN violates the total int domain required by both open-address indexes",
    )

    revise(
        "arena-generation-interner",
        header=r'''struct InternId{std::uint32_t slot;std::uint32_t generation;};class ArenaGenerationInterner{public:ArenaGenerationInterner(std::size_t,std::size_t);std::optional<InternId> intern(std::string_view);std::optional<std::string> resolve(InternId)const;bool release(InternId);std::size_t bytes_used()const;private:struct Entry{std::size_t offset=0;std::size_t size=0;std::uint32_t generation=1;std::size_t refs=0;bool live=false;};std::vector<char> arena_;std::size_t used_=0;std::vector<Entry> slots_;std::vector<std::pair<std::size_t,std::size_t>> free_;std::vector<std::optional<std::size_t>> index_;void coalesce();std::size_t hash(std::string_view)const;std::optional<std::size_t> indexed(std::string_view)const;void rebuild_index();};''',
        reference=r'''ArenaGenerationInterner::ArenaGenerationInterner(std::size_t b,std::size_t s):arena_(b),slots_(s),free_{{0,b}},index_(s){if(!b||!s)throw std::invalid_argument("capacity");}void ArenaGenerationInterner::coalesce(){std::sort(free_.begin(),free_.end());std::vector<std::pair<std::size_t,std::size_t>> out;for(auto e:free_){if(!out.empty()&&out.back().first+out.back().second==e.first)out.back().second+=e.second;else out.push_back(e);}free_=std::move(out);}std::size_t ArenaGenerationInterner::hash(std::string_view v)const{std::size_t h=0;for(unsigned char c:v)h=(h*131+c)%index_.size();return h;}std::optional<std::size_t> ArenaGenerationInterner::indexed(std::string_view v)const{auto h=hash(v);for(std::size_t p=0;p<index_.size();++p){auto at=(h+p)%index_.size();if(!index_[at])return std::nullopt;auto slot=*index_[at];const auto&e=slots_[slot];if(e.live&&e.size==v.size()&&std::equal(v.begin(),v.end(),arena_.begin()+static_cast<std::ptrdiff_t>(e.offset)))return slot;}return std::nullopt;}void ArenaGenerationInterner::rebuild_index(){std::fill(index_.begin(),index_.end(),std::nullopt);for(std::size_t slot=0;slot<slots_.size();++slot)if(slots_[slot].live){const auto&e=slots_[slot];std::string_view value(arena_.data()+e.offset,e.size);auto h=hash(value);for(std::size_t p=0;p<index_.size();++p){auto at=(h+p)%index_.size();if(!index_[at]){index_[at]=slot;break;}}}}std::optional<InternId> ArenaGenerationInterner::intern(std::string_view v){if(auto found=indexed(v)){auto&e=slots_[*found];if(e.refs==std::numeric_limits<std::size_t>::max())throw std::overflow_error("refs");++e.refs;return InternId{static_cast<std::uint32_t>(*found),e.generation};}auto slot=std::find_if(slots_.begin(),slots_.end(),[](const auto&e){return !e.live;});if(slot==slots_.end())return std::nullopt;std::size_t offset=0;if(!v.empty()){auto extent=std::find_if(free_.begin(),free_.end(),[&](auto e){return e.second>=v.size();});if(extent==free_.end())return std::nullopt;offset=extent->first;extent->first+=v.size();extent->second-=v.size();if(!extent->second)free_.erase(extent);std::copy(v.begin(),v.end(),arena_.begin()+static_cast<std::ptrdiff_t>(offset));}slot->offset=offset;slot->size=v.size();slot->refs=1;slot->live=true;used_+=v.size();rebuild_index();auto id=static_cast<std::size_t>(slot-slots_.begin());return InternId{static_cast<std::uint32_t>(id),slot->generation};}std::optional<std::string> ArenaGenerationInterner::resolve(InternId id)const{if(id.slot>=slots_.size())return std::nullopt;const auto&e=slots_[id.slot];if(!e.live||e.generation!=id.generation)return std::nullopt;return std::string(arena_.begin()+static_cast<std::ptrdiff_t>(e.offset),arena_.begin()+static_cast<std::ptrdiff_t>(e.offset+e.size));}bool ArenaGenerationInterner::release(InternId id){if(id.slot>=slots_.size())return false;auto&e=slots_[id.slot];if(!e.live||e.generation!=id.generation)return false;if(e.refs>1){--e.refs;return true;}if(e.generation==std::numeric_limits<std::uint32_t>::max())throw std::overflow_error("generation");if(e.size)free_.push_back({e.offset,e.size});used_-=e.size;e.live=false;e.refs=0;++e.generation;coalesce();rebuild_index();return true;}std::size_t ArenaGenerationInterner::bytes_used()const{return used_;}''',
        hidden=r'''int main(){ArenaGenerationInterner i(8,3);auto a=i.intern("a");auto d=i.intern("d");CHECK(a&&d&&a->slot!=d->slot);auto same=i.intern("d");CHECK(same&&same->slot==d->slot);CHECK(i.release(*d)&&i.resolve(*same)=="d");CHECK(i.release(*same));CHECK(!i.resolve(*d));auto empty=i.intern("");CHECK(empty&&i.resolve(*empty)=="");return failures;}''',
        negative_old='for(std::size_t p=0;p<index_.size();++p){auto at=(h+p)%index_.size();',
        negative_new='for(std::size_t p=0;p<1;++p){auto at=(h+p)%index_.size();',
        negative_reason="checking only the home cell misses a colliding live string and creates a duplicate ID instead of using the open-address index",
    )

    return tuple(by[case.task_id] for case in cases)
